    @inline(__always)
    private func checkSet4ConstantA(_ value: H.Lane) {
        let mismatches = Mismatches("set4 with a repeating \(hex(value))")
        let tupleInputs = Inputs.tuples4(
            of: Inputs.vectors(H.Vector.self, seed: 0xC788_D008_511C_BDB7)
        )
        let indexInputs = Inputs.tupleIndices(count: 4)
        mismatches.check(
            H.repeating(value),
            H.Vector(raw: HighwayReference.repeatingBF16(value.bitPattern)),
            "repeating"
        )
        for (tuple, index) in everyPair(tupleInputs, indexInputs) {
            let port = H.set4(tuple, at: index, to: H.repeating(value))
            let reference = { tuple in
                (
                    H.Vector(raw: tuple.v0), H.Vector(raw: tuple.v1), H.Vector(raw: tuple.v2),
                    H.Vector(raw: tuple.v3)
                )
            }(
                HighwayReference.set4BF16(
                    cvectorization_ops_tuple4_bf16(
                        v0: tuple.0.raw,
                        v1: tuple.1.raw,
                        v2: tuple.2.raw,
                        v3: tuple.3.raw
                    ),
                    index,
                    H.repeating(value).raw
                )
            )
            mismatches.check(
                port.0,
                reference.0,
                "tuple: \([describe(tuple.0), describe(tuple.1), describe(tuple.2), describe(tuple.3)].joined(separator: ", ")), index: \(index)"
            )
            mismatches.check(
                port.1,
                reference.1,
                "tuple: \([describe(tuple.0), describe(tuple.1), describe(tuple.2), describe(tuple.3)].joined(separator: ", ")), index: \(index)"
            )
            mismatches.check(
                port.2,
                reference.2,
                "tuple: \([describe(tuple.0), describe(tuple.1), describe(tuple.2), describe(tuple.3)].joined(separator: ", ")), index: \(index)"
            )
            mismatches.check(
                port.3,
                reference.3,
                "tuple: \([describe(tuple.0), describe(tuple.1), describe(tuple.2), describe(tuple.3)].joined(separator: ", ")), index: \(index)"
            )
        }
        mismatches.record()
    }

